ideo_rows = [[k, v[0], v[1], v[2], v[3]] for k, v in IDEO.items()]

def defaults(tags, plus=""):
    seen = []
    for t in tags.split("+"):
        t = t.strip()
        if t in IDEO:
            for x in IDEO[t][1].split(","):
                x = x.strip()
                if x and x not in seen:
                    seen.append(x)
    for x in plus.split(","):
        x = x.strip()
        if x and x not in seen:
            seen.insert(0, x)
    return ", ".join(seen)

